import{_ as e,a,c as t}from"./chunks/framework.BkXmWmgX.js";const f=JSON.parse('{"title":"디자이너 또한 기술적 소양을 갖춰야 한다. 그렇다면 프론트엔드 개발자는? | OTW for FE","titleTemplate":false,"description":"","frontmatter":{"layout":"post","title":"OTW for FE","titleTemplate":false,"lang":"ko"},"headers":[],"params":{"id":"319e548d-8a8e-805e-a50f-fe83a5bcf5e9","title":"디자이너 또한 기술적 소양을 갖춰야 한다. 그렇다면 프론트엔드 개발자는?","date":"2026-03-12","coverUrl":"/kudzu-based-bench/assets/notion/0ea47e2e7be84540.png","html":"<h1 data-notion-block-id=\\"319e548d-8a8e-802e-8e86-d5042b689bfc\\">Beyond the Article: 한 걸음 더</h1><h2 data-notion-block-id=\\"31ee548d-8a8e-805e-997b-c37772e59dd5\\" id=\\"31ee548d-8a8e-805e-997b-c37772e59dd5\\">디자이너 또한 기술적 소양을 갖춰야 한다. 그렇다면 프론트엔드 개발자는?</h2><a href=\\"https://www.doc.cc/articles/craft-crisis\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.doc.cc/articles/craft-crisis</a><p data-notion-block-id=\\"31ee548d-8a8e-80c4-9980-f5145ae853ea\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/1f3e548d-8a8e-8063-b8ed-f6bef2f275d2#1f3e548d-8a8e-80cf-a0f1-d24b16bd78e1\\">Figma site 사태</a>와 여러 AI 도구의 등장은 디자이너에게 기술적 소양을 요구하고 있습니다. 하지만 이는 비단 디자이너에게만 국한된 이야기가 아닙니다. 프론트엔드 개발자 역시 마찬가지입니다. 프론트엔드 개발자가 디자인, 기획, 비즈니스 의사결정에 적극적으로 참여해야 함을 의미합니다. 더 나아가, 화면 뒤에 감춰진 백엔드와 인프라의 제약 사항을 이해하여 팀에 올바른 방향을 제시하고, 다른 동료나 AI가 작성한 코드 속에서 프론트엔드 생태계 특유의 수많은 제약사항을 예리하게 분석하고 검증해 낼 수 있어야 합니다.</p><h2 data-notion-block-id=\\"319e548d-8a8e-80be-b606-dfd9cebc6966\\" id=\\"319e548d-8a8e-80be-b606-dfd9cebc6966\\">React Aria는 왜 네이티브 <code>&#x3C;dialog></code>를 쓰지 않을까</h2><a href=\\"https://github.com/adobe/react-spectrum/discussions/9696#discussioncomment-15942257\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/adobe/react-spectrum/discussions/9696#discussioncomment-15942257</a><p data-notion-block-id=\\"319e548d-8a8e-80d2-bc42-d5c843f15b8f\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/2afe548d-8a8e-80ae-99f2-d8d66f5a43a2#2b5e548d-8a8e-80b2-9861-d36ff5c37a09\\"><code>&#x3C;dialog></code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/2afe548d-8a8e-80ae-99f2-d8d66f5a43a2#2b5e548d-8a8e-80b2-9861-d36ff5c37a09\\">는 모던 브라우저에서 모두 지원</a>하는데도, 왜 React Aria같은 Headless 라이브러리들에서 사용하지 않는지, 그리고 최신 HTML, CSS 기능이 아직은 널리 적용하기엔 시기상조인지 보여주는 글입니다(ex. <a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2bfe548d-8a8e-80d9-9daf-fbdd34207391\\">sonner 제작기. 그리고 마주친 문제들</a>).</p><h2 data-notion-block-id=\\"319e548d-8a8e-8033-8568-e77ed92ca509\\" id=\\"319e548d-8a8e-8033-8568-e77ed92ca509\\"><code>&#x3C;Activity/></code>를 통해 자연스러운 Video 시청 경험 제공</h2><a href=\\"https://www.mux.com/blog/react-is-changing-the-game-for-streaming-apps-with-the-activity-component\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.mux.com/blog/react-is-changing-the-game-for-streaming-apps-with-the-activity-component</a><p data-notion-block-id=\\"31ee548d-8a8e-809c-bc20-f58c155c2361\\">React 19.2에 새로 나온 <code>&#x3C;Activity/></code>를 통해 Video player가 가려졌을 경우에 Video 시청 경험을 자연스러운 방식으로 진행되도록 어떻게 구현하는지 소개하는 글입니다. Video가 아니더라도, DOM 상태를 저장하고 다시 재개하는데에 아주 적합한 기능으로서 알아두면 좋아보입니다. 비슷하게 <a href=\\"https://ones-to-watch.ethansup.net/news/post/304e548d-8a8e-802a-9994-c2dccff3d80a#305e548d-8a8e-80df-987b-f71fea6f9efe\\">React의 종료 애니메이션 문제</a>도 같이 보면 좋습니다.</p><h2 data-notion-block-id=\\"31ee548d-8a8e-8099-8c8b-ff77f75cf7b6\\" id=\\"31ee548d-8a8e-8099-8c8b-ff77f75cf7b6\\">7년간의 TypeScript 마이그레이션, 어떻게 진행했는가</h2><a href=\\"https://www.patreon.com/posts/seven-years-to-typescript-152144830\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.patreon.com/posts/seven-years-to-typescript-152144830</a><p data-notion-block-id=\\"319e548d-8a8e-8078-8ea4-f1f22c2883d1\\">7년간 마이그레이션을 진행하면서 적용한 세 가지 마이그레이션 방식을 소개하면서 장단을 간단하게 소개합니다. 그리고 가장 주목할만한 AI를 통한 마이그레이션을 자세히 소개하고 있습니다. 비슷하게 <a href=\\"https://ones-to-watch.ethansup.net/news/post/2b7e548d-8a8e-8097-bf24-f20f9aaf3bc7#2bce548d-8a8e-80f2-942f-daed2f7240f4\\">Enzyme에서 RTL로, 계획적으로, 자동으로 바꾸기</a>또한 마이그레이션을 설계하고 어떻게 마이그레이션을 이끌어갔는지 자세하게 소개하므로 한 번 보시길 추천드립니다.</p><h2 data-notion-block-id=\\"31ee548d-8a8e-80ae-8ca7-e825a07c4356\\" id=\\"31ee548d-8a8e-80ae-8ca7-e825a07c4356\\">AI 채팅기능을 만들 때 필요한 UX</h2><a href=\\"https://medium.com/doctolib/building-reliable-ai-chat-on-mobile-01015d74422e\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/doctolib/building-reliable-ai-chat-on-mobile-01015d74422e</a><p data-notion-block-id=\\"31ee548d-8a8e-8046-9076-c5336109e94e\\">기본적인 채팅 기능을 만들 때와 다르게 AI 채팅 기능은 어떤 UX를 담아야 하는지, 그리고 어떻게 UX를 구현하는데 무엇이 필요했는지 소개하는 글입니다. React Native 라이브러리를 어떻게 만들었는지, Tanstack Query를 어떻게 사용했는지를 소개하는 글이지만, UX 구현 방식과 Tanstack Query의 사용법은 웹 프론트엔드에도 적용되므로 AI 채팅 UX에 관심이 있다면 보시길 추천드립니다.</p><h2 data-notion-block-id=\\"319e548d-8a8e-806c-9f20-e84208791085\\" id=\\"319e548d-8a8e-806c-9f20-e84208791085\\">JavaScript-only DRM은 의미가 없다</h2><a href=\\"https://www.therantydev.com/javascript-drms-are-stupid\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.therantydev.com/javascript-drms-are-stupid</a><p data-notion-block-id=\\"31ee548d-8a8e-80dc-b325-f4bda76e188c\\">JS-only DRM을 리버스 엔지니어링을 하면서 하드웨어 기반 DRM이 아니라면 DRM 보안이 의미 없음을 소개하는 글입니다. DRM의 기본과 JS-only DRM을 리버스 엔지니어링하는 글이라 프론트엔드의 지식과는 약간 거리가 있지만, 기본적으로 웹 브라우저 환경이라는 클라이언트의 보안 한계를 알고 아키텍쳐링할 때 주의해야 함을 다시 상기시켜주는 글입니다.</p><h1 data-notion-block-id=\\"319e548d-8a8e-8095-954c-f0dd952fdfb3\\">Straight to the Article: 빛나는 인사이트</h1><h2 data-notion-block-id=\\"319e548d-8a8e-80ea-8814-c440da3b4137\\" id=\\"319e548d-8a8e-80ea-8814-c440da3b4137\\">봇 검사 UI 리디자인, 어느 것이 필요할까</h2><a href=\\"https://blog.cloudflare.com/the-most-seen-ui-on-the-internet-redesigning-turnstile-and-challenge-pages/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/the-most-seen-ui-on-the-internet-redesigning-turnstile-and-challenge-pages/</a><p data-notion-block-id=\\"31ee548d-8a8e-8057-8701-e809aa9f5808\\">가장 많이 마주치고, 가장 싫어하는 UI/UX인 봇 검사 UI에서 어느 방식으로 사용자 경험을 좋게 할지 설계했는지, 그리고 어느 부분에서의 접근성 준수를 했는지 소개합니다.</p><h2 data-notion-block-id=\\"319e548d-8a8e-807c-a012-eefbad356cae\\" id=\\"319e548d-8a8e-807c-a012-eefbad356cae\\">RSC 렌더링 중 에러가 발생한다면</h2><a href=\\"https://twofoldframework.com/blog/error-rendering-with-rsc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://twofoldframework.com/blog/error-rendering-with-rsc</a><p data-notion-block-id=\\"31ee548d-8a8e-8075-babd-d7dd8f5cdd2e\\">RSC 렌더링 중 에러가 발생했을 때 RSC / SSR / CSR 환경에서 어떻게 처리하는지 상세하게 보여주는 글입니다. RSC 렌더링을 메타 프레임워크가 보통 다루므로 직접 처리하는 경우는 적지만, 알아두면 좋을듯합니다.</p><h2 data-notion-block-id=\\"31ee548d-8a8e-8014-8beb-cf7d6b6b0fb5\\" id=\\"31ee548d-8a8e-8014-8beb-cf7d6b6b0fb5\\">격리는 무엇이고, WASM은 어느 수준의 \\"격리\\"를 제공하는가?</h2><a href=\\"https://www.shayon.dev/post/2026/52/lets-discuss-sandbox-isolation/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.shayon.dev/post/2026/52/lets-discuss-sandbox-isolation/</a><h2 data-notion-block-id=\\"319e548d-8a8e-80f1-bd72-fb367f5bb60e\\" id=\\"319e548d-8a8e-80f1-bd72-fb367f5bb60e\\">React Fiber는 왜 생겨났을까?</h2><a href=\\"https://inside-react.vercel.app/blog/understanding-why-react-fiber-exists\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://inside-react.vercel.app/blog/understanding-why-react-fiber-exists</a><h2 data-notion-block-id=\\"319e548d-8a8e-8044-88f2-d02cecff3f2d\\" id=\\"319e548d-8a8e-8044-88f2-d02cecff3f2d\\">왜 WASM은 아직 JS를 통해서 실행되어야 하는가</h2><a href=\\"https://hacks.mozilla.org/2026/02/making-webassembly-a-first-class-language-on-the-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hacks.mozilla.org/2026/02/making-webassembly-a-first-class-language-on-the-web/</a><h2 data-notion-block-id=\\"31ee548d-8a8e-80da-9a26-e3b93b5b9c6a\\" id=\\"31ee548d-8a8e-80da-9a26-e3b93b5b9c6a\\">React Native 2025 설문조사 결과</h2><a href=\\"https://results.2025.stateofreactnative.com/en-US/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://results.2025.stateofreactnative.com/en-US/</a><h1 data-notion-block-id=\\"319e548d-8a8e-80ef-a7a7-cf8bd42d19ed\\">Fresh Finds: 놓치지 말아야 할 소식</h1><a href=\\"https://github.com/solidjs/solid/releases/tag/v2.0.0-beta.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/solidjs/solid/releases/tag/v2.0.0-beta.0</a><p data-notion-block-id=\\"319e548d-8a8e-80d1-ae26-dfcf7e2e081a\\">SolidJS 2버전이 되면서 <code>&#x3C;Suspense></code>를 버리고 계산이 모두 Promise를 반환하도록 지원한다는 소식입니다(아직은 베타 버전이지만요)</p><a href=\\"https://expo.dev/changelog/sdk-55\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://expo.dev/changelog/sdk-55</a><p data-notion-block-id=\\"319e548d-8a8e-80af-a60e-d3da373672e8\\">Expo가 55버전이 되면서 수많은 새로운 기능을 추가했다는 소식입니다.</p>"},"relativePath":"news/post/319e548d-8a8e-805e-a50f-fe83a5bcf5e9.md","filePath":"news/post/[id].md"}'),o={name:"news/post/319e548d-8a8e-805e-a50f-fe83a5bcf5e9.md"};function d(s,r,c,n,i,l){return a(),t("div")}const h=e(o,[["render",d]]);export{f as __pageData,h as default};
